RUSTFLAGS=-Awarnings cargo test --package ripgrep --test integration -- multiline::replacement

cd /testbed && printf 'foo\nbar\n' | target/debug/rg --no-config --color never -NUrX 'foo\nbar|\z' && python3 - <<'PY'
from pathlib import Path
path = Path('crates/printer/src/util.rs')
text = path.read_text()
old = '''    /// matches with the given replacement. To access the result of the
    /// replacement, use the `replacement` method.
'''
new = '''    /// matches in the given range with the given replacement. Bytes outside
    /// the range are used only for context. To access the result of the
    /// replacement, use the `replacement` method.
'''
assert text.count(old) == 1
text = text.replace(old, new)
old = '''            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
'''
new = '''            let mut last_match = range.start;
            matcher
                .captures_iter_at(subject, range.start, caps, |caps| {
                    let m = caps.get(0).unwrap();
                    if m.start() >= range.end {
                        return false;
                    }
                    dst.extend_from_slice(&subject[last_match..m.start()]);
                    last_match = m.end();
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                })
                .map_err(io::Error::error_message)?;
            let end = std::cmp::min(subject.len(), range.end);
            if last_match < end {
                dst.extend_from_slice(&subject[last_match..end]);
            }
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))
path = Path('tests/multiline.rs')
text = path.read_text()
anchor = 'rgtest!(replacement_lookaround,'
assert text.count(anchor) == 1
addition = r'''rgtest!(replacement_empty_end, |dir: Dir, mut cmd: TestCommand| {
    dir.create("test", "foo\nbar\n");
    cmd.args(&["-NU", "-r", "X", r"foo\nbar|\z", "test"]);
    eqnice!("X\n", cmd.stdout());
});

'''
path.write_text(text.replace(anchor, addition + anchor))
path = Path('CHANGELOG.md')
text = path.read_text()
anchor = 'Bug fixes:\n\n'
assert text.count(anchor) >= 1
path.write_text(text.replace(anchor, anchor + '* Fix multiline replacements including or replacing content beyond the matching\n  lines.\n', 1))
PY
